mapper.select:

WHERE r.admin_dong_id = #{adminDongId}
AND r.status = 'ACTIVE'
ORDER BY r.created_at DESC, r.review_id DESC


WHERE r.user_id = #{userId}
AND r.status != 'DELETED'
ORDER BY r.created_at DESC, r.review_id DESC

SELECT rs.review_id, rs.review_category_id, rc.code AS category_code, rs.score FROM review_scores rs INNER JOIN review_categories rc ON rc.review_category_id = rs.review_category_id WHERE rs.review_id IN
#{reviewId}
ORDER BY rs.review_id, rs.review_category_id

SELECT COUNT(*)
FROM admin_dongs
WHERE admin_dong_id = #{adminDongId}
